insert
  into member
  		(
	  		 mem_no, mem_id, mem_pw, mem_name
	  	 , mem_email, mem_nickname, mem_phone
			 , gender, birth_year
  		)
  values
  		(
	  		 seq_mno.nextval
	  	 , #{memId}, #{memPw}, #{memName}
	  	 , #{memEmail}, #{memNickname}, #{memPhone}
	  	 , #{gender}, #{birthYear}
  		)

